import sympy as sp
r = sp.symbols('r')
phi, psi = (1 + sp.sqrt(5))/2, (1 - sp.sqrt(5))/2
assert set(sp.solve(r**2 - r - 1, r)) == {phi, psi} and sp.simplify(phi - psi - sp.sqrt(5)) == 0
F = [0, 1]
for _ in range(40): F.append(F[-1] + F[-2])
for n in range(40):
    assert sp.expand((phi**n - psi**n)/sp.sqrt(5)) == F[n]
a, b = sp.symbols('alpha beta')
assert sp.solve([a + b, a*phi + b*psi - 1], [a, b]) == {a: 1/sp.sqrt(5), b: -1/sp.sqrt(5)}

import itertools
def best(n):
    odd = [s for s in range(1, 2**n) if bin(s).count('1') % 2 == 1]
    ok = {(a, b) for a in odd for b in odd if bin(a & b).count('1') % 2 == 0}
    bestsize = 0
    def grow(chosen, cands):
        nonlocal bestsize
        bestsize = max(bestsize, len(chosen))
        for i, c in enumerate(cands):
            grow(chosen + [c], [d for d in cands[i+1:] if (c, d) in ok])
    grow([], odd)
    return bestsize
assert [best(n) for n in range(1, 6)] == [1, 2, 3, 4, 5]

